import fs from 'node:fs';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';import {createRequire} from 'node:module';import {DatabaseSync} from 'node:sqlite';import {execFileSync} from 'node:child_process';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {collectDiscoveryHealth} from './src/newsFlow/discoveryHealth.mjs';const root='/var/lib/news-flow/qc-recover25-20261122',require=createRequire('/opt/news-flow/current/package.json'),dotenv=require('dotenv'),ES=require('elasticsearch'),sha=x=>createHash('sha256').update(x).digest('hex'),env=dotenv.parse(fs.readFileSync('/etc/news-flow/news.env')),es=new ES.Client({host:env.ES5_HOST,apiVersion:'5.6',log:[],maxRetries:0,requestTimeout:15000}),db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),registry=await loadNewsRegistry(),cohort=JSON.parse(fs.readFileSync('/var/lib/news-flow/qc-close25-20261122/cohort.json')),q=JSON.parse(fs.readFileSync(root+'/cnn-qualified.json')),apply=JSON.parse(fs.readFileSync(root+'/cnn-apply-result.json')),r={at:new Date().toISOString(),esReadback:[],services:execFileSync('systemctl',['show','news-flow-seed','news-flow-parse','news-flow-import','-p','Id,MainPID,ActiveState,NRestarts'],{encoding:'utf8'}),cnnConfigSha:sha(fs.readFileSync(apply.file)),aiUsage:db.prepare('SELECT * FROM ai_usage ORDER BY day').all()};
